draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // dog body
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 70);
  ctx.lineTo(W/2 - 25, H/2 - 90);
  ctx.lineTo(W/2 - 5, H/2 - 90);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 - 70);
  ctx.lineTo(W/2 + 25, H/2 - 90);
  ctx.lineTo(W/2 + 5, H/2 - 90);
  ctx.stroke();

  // tail
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 + 30);
  ctx.lineTo(W/2 - 15, H/2 + 60);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 + 30);
  ctx.lineTo(W/2 + 15, H/2 + 60);
  ctx.stroke();

  // favorite person
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 20 * Math.cos(t), H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // excitement lines
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 + 50 + 10 * Math.sin(t), H/2 - 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 - 50 - 10 * Math.sin(t), H/2 - 70);
  ctx.stroke();

  ctx.restore();
}
